fn rg_main(p: vec2<u32>) {
  let q = vec2<i32>(p);
  let n0_c0 = textureLoad(rg_in_src, clamp(q + vec2<i32>(0, 0), vec2<i32>(0), vec2<i32>(textureDimensions(rg_in_src)) - vec2<i32>(1)), 0);
  let n0_z0 = vec4<f32>(textureLoad(rg_in_depth, clamp(q + vec2<i32>(0, 0), vec2<i32>(0), vec2<i32>(textureDimensions(rg_in_depth)) - vec2<i32>(1)), 0)).x;
  let n0_n0 = textureLoad(rg_in_normal, clamp(q + vec2<i32>(0, 0), vec2<i32>(0), vec2<i32>(textureDimensions(rg_in_normal)) - vec2<i32>(1)), 0).xyz;
  var n0_acc = vec4<f32>(0.0);
  var n0_w = 0.0;
  for (var n0_y = -4; n0_y <= 4; n0_y++) {
    for (var n0_x = -4; n0_x <= 4; n0_x++) {
      let n0_c = textureLoad(rg_in_src, clamp(q + vec2<i32>(n0_x * 2, n0_y * 2), vec2<i32>(0), vec2<i32>(textureDimensions(rg_in_src)) - vec2<i32>(1)), 0);
      let n0_dl = dot(n0_c.rgb - n0_c0.rgb, vec3<f32>(0.2126, 0.7152, 0.0722));
      let n0_dz = vec4<f32>(textureLoad(rg_in_depth, clamp(q + vec2<i32>(n0_x * 2, n0_y * 2), vec2<i32>(0), vec2<i32>(textureDimensions(rg_in_depth)) - vec2<i32>(1)), 0)).x - n0_z0;
      let n0_nd = max(dot(textureLoad(rg_in_normal, clamp(q + vec2<i32>(n0_x * 2, n0_y * 2), vec2<i32>(0), vec2<i32>(textureDimensions(rg_in_normal)) - vec2<i32>(1)), 0).xyz, n0_n0), 0.0);
      let n0_k = exp(-(n0_dl * n0_dl) / (2.0 * 0.6 * 0.6)) * exp(-abs(n0_dz) / 0.002) * pow(n0_nd, 32.0);
      n0_acc += n0_k * n0_c;
      n0_w += n0_k;
    }
  }
  let n0_value = n0_acc / max(n0_w, 0.000001);
  let n0_weight = n0_w;
  textureStore(rg_out_dst, p, n0_value);
}
